/*
 * Clear legacy Chirpy PWA caches.
 *
 * The site is content-first and updates frequently, so offline caching can make
 * the homepage look stale even after GitHub Pages has deployed successfully.
 */
self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith("chirpy-"))
            .map((key) => caches.delete(key))
        )
      )
      .then(() => self.clients.claim())
      .then(() => self.registration.unregister())
  );
});
